const {JSDOM}=require('jsdom'),fs=require('fs'),assert=require('node:assert/strict'),path=require('path');
const base=path.resolve(__dirname,'../students'),dom=new JSDOM(fs.readFileSync(base+'/labs.html','utf8'),{url:'https://example.test/students/labs.html#stability',runScripts:'outside-only'}),w=dom.window;
for(const p of ['lab-models.js','study-export.js','labs.js'])w.eval(fs.readFileSync(base+'/'+p,'utf8'));
let n=0;const ok=(v,s)=>{assert.ok(v,s);n++},E=w.MT_STUDY_EXPORT;
for(const id of ['stability','controls','engine']){const s=w.MT_LAB_SNAPSHOT(id),xml=new JSDOM(s.charts[0].svg,{contentType:'image/svg+xml'}),html=E.report(s),report=new JSDOM(html),d=report.window.document;ok(xml.window.document.documentElement.namespaceURI==='http://www.w3.org/2000/svg','standalone XML SVG '+id);ok(d.querySelector('svg path,svg rect'),'embedded '+id+' graph');ok(d.querySelectorAll('table').length>=3,'inputs/results/data table '+id);ok(!html.includes('src="http'),'no external asset dependency '+id);ok(JSON.parse(d.getElementById('study-snapshot').textContent).model==='labs-'+id,'embedded snapshot JSON '+id);ok(d.body.textContent.includes('Model, equations and assumptions'),'assumptions '+id)}
const x=E.report({model:'test',title:'<img src=x onerror=alert(1)>',inputs:{'<script>':'</script><script>alert(1)</script>'},results:{value:1},notes:['<b>literal</b>']});const xd=new JSDOM(x).window.document;
ok(!xd.querySelector('img'),'title escaped');ok(xd.querySelectorAll('script').length===1,'no script injection');ok(JSON.parse(xd.getElementById('study-snapshot').textContent).inputs['<script>'].startsWith('</script>'),'embedded JSON remains valid after HTML escaping');
assert.throws(()=>E.report({model:'x',title:'x',inputs:{},results:{x:NaN}}));n++;
const raw=E.scenario('labs-engine',{engine:{rpm:600}}),restore=E.parseScenario(raw,'labs-engine',['engine']);ok(restore.engine.rpm===600,'scenario round trip');assert.throws(()=>E.parseScenario(raw,'labs-stability',['stability']));n++;assert.throws(()=>E.parseScenario(raw.replace('"version": 1','"version": 2'),'labs-engine',['engine']));n++;
const csv=E.csv([['value'],['=1+1'],[-3],['+cmd'],['normal,"quoted"']]);ok(csv.includes("\"'=1+1\"")&&csv.includes('"-3"'),'CSV formula protection and negative numbers');ok(csv.includes('"normal,""quoted"""'),'CSV quoting');
const input=w.document.querySelector('#stability-form [name=displacement]');input.value='0';input.dispatchEvent(new w.Event('change',{bubbles:true}));assert.throws(()=>w.MT_LAB_SNAPSHOT('stability'));n++;
input.value='10000';input.dispatchEvent(new w.Event('change',{bubbles:true}));ok(w.MT_LAB_SNAPSHOT('stability').results.stability.includes('Corrected GM'),'valid calculation export restored');
